clamp_prob <- function(
    p,
    eps = 1e-7
) {
  pmin(
    pmax(
      as.numeric(p),
      eps
    ),
    1 - eps
  )
}

fast_auc <- function(
    y,
    p
) {
  keep <- !is.na(y) &
    !is.na(p) &
    is.finite(p)

  y <- as.integer(
    y[keep]
  )
  p <- as.numeric(
    p[keep]
  )

  keep2 <- y %in% c(
    0L,
    1L
  )

  y <- y[keep2]
  p <- p[keep2]

  n1 <- as.double(
    sum(
      y == 1L
    )
  )
  n0 <- as.double(
    sum(
      y == 0L
    )
  )

  if (
    n1 == 0 ||
      n0 == 0
  ) {
    return(NA_real_)
  }

  r <- rank(
    p,
    ties.method = "average"
  )

  (
    sum(
      r[
        y == 1L
      ]
    ) -
      n1 *
        (
          n1 + 1
        ) /
        2
  ) /
    (
      n1 *
        n0
    )
}

fast_auprc <- function(
    y,
    p
) {
  keep <- !is.na(y) &
    !is.na(p) &
    is.finite(p)

  y <- as.integer(
    y[keep]
  )
  p <- as.numeric(
    p[keep]
  )

  keep2 <- y %in% c(
    0L,
    1L
  )

  y <- y[keep2]
  p <- p[keep2]

  n_pos <- sum(
    y == 1L
  )

  if (n_pos == 0L) {
    return(NA_real_)
  }

  ord <- order(
    p,
    decreasing = TRUE
  )
  yy <- y[ord]

  tp <- cumsum(
    yy == 1L
  )
  fp <- cumsum(
    yy == 0L
  )

  precision <- tp /
    (
      tp +
        fp
    )

  recall <- tp /
    n_pos

  recall_previous <- c(
    0,
    head(
      recall,
      -1L
    )
  )

  sum(
    precision *
      (
        recall -
          recall_previous
      ),
    na.rm = TRUE
  )
}

binary_calibration <- function(
    y,
    p
) {
  keep <- !is.na(y) &
    !is.na(p) &
    is.finite(p)

  y <- as.integer(
    y[keep]
  )
  p <- clamp_prob(
    p[keep]
  )

  if (
    length(
      unique(
        y
      )
    ) <
      2L
  ) {
    return(
      c(
        intercept = NA_real_,
        slope = NA_real_
      )
    )
  }

  lp <- qlogis(
    p
  )

  fit_i <- tryCatch(
    glm(
      y ~ 1,
      family = binomial(),
      offset = lp
    ),
    error = function(e) NULL
  )

  fit_s <- tryCatch(
    glm(
      y ~ lp,
      family = binomial()
    ),
    error = function(e) NULL
  )

  c(
    intercept =
      if (
        is.null(
          fit_i
        )
      ) {
        NA_real_
      } else {
        unname(
          coef(
            fit_i
          )[1L]
        )
      },
    slope =
      if (
        is.null(
          fit_s
        )
      ) {
        NA_real_
      } else {
        unname(
          coef(
            fit_s
          )["lp"]
        )
      }
  )
}

binary_metrics <- function(
    y,
    p
) {
  pp <- clamp_prob(
    p
  )
  cal <- binary_calibration(
    y,
    p
  )

  data.table(
    N = length(
      y
    ),
    events = sum(
      y == 1L
    ),
    prevalence = mean(
      y == 1L
    ),
    AUROC = fast_auc(
      y,
      p
    ),
    AUPRC = fast_auprc(
      y,
      p
    ),
    AUPRC_to_prevalence =
      fast_auprc(
        y,
        p
      ) /
        mean(
          y == 1L
        ),
    Brier = mean(
      (
        p -
          y
      )^2
    ),
    log_loss =
      -mean(
        y *
          log(
            pp
          ) +
          (
            1 -
              y
          ) *
            log(
              1 -
                pp
            )
      ),
    calibration_intercept =
      unname(
        cal[
          "intercept"
        ]
      ),
    calibration_slope =
      unname(
        cal[
          "slope"
        ]
      )
  )
}

pinball_loss <- function(
    y,
    q,
    alpha
) {
  e <- y - q

  mean(
    ifelse(
      e >= 0,
      alpha *
        e,
      (
        alpha -
          1
      ) *
        e
    ),
    na.rm = TRUE
  )
}

duration_metrics <- function(
    y,
    q10,
    q50,
    q90
) {
  coverage <- mean(
    y >=
      q10 &
      y <=
        q90
  )

  data.table(
    N = length(
      y
    ),
    median_MAE_days =
      mean(
        abs(
          y -
            q50
        )
      ),
    median_bias_days =
      median(
        q50 -
          y
      ),
    mean_pinball =
      mean(
        c(
          pinball_loss(
            y,
            q10,
            0.10
          ),
          pinball_loss(
            y,
            q50,
            0.50
          ),
          pinball_loss(
            y,
            q90,
            0.90
          )
        )
      ),
    empirical_q10 =
      mean(
        y <=
          q10
      ),
    empirical_q50 =
      mean(
        y <=
          q50
      ),
    empirical_q90 =
      mean(
        y <=
          q90
      ),
    central_80_coverage =
      coverage,
    median_80_range_width_days =
      median(
        q90 -
          q10
      )
  )
}

bootstrap_binary_ci <- function(
    y,
    p,
    B = B_CLASSIFICATION,
    workers = BOOTSTRAP_WORKERS,
    seed = 20260913L
) {
  y <- as.integer(
    y
  )
  p <- as.numeric(
    p
  )
  n <- length(
    y
  )

  point <- binary_metrics(
    y,
    p
  )

  worker_metric <- function(
      b,
      y,
      p,
      seed
  ) {
    set.seed(
      seed +
        b
    )

    idx <- sample.int(
      length(
        y
      ),
      replace = TRUE
    )

    yy <- y[
      idx
    ]
    pp <- p[
      idx
    ]

    auc_local <- function(y, p) {
      n1 <- as.double(
        sum(
          y == 1L
        )
      )
      n0 <- as.double(
        sum(
          y == 0L
        )
      )

      if (
        n1 == 0 ||
          n0 == 0
      ) {
        return(
          NA_real_
        )
      }

      r <- rank(
        p,
        ties.method = "average"
      )

      (
        sum(
          r[
            y == 1L
          ]
        ) -
          n1 *
            (
              n1 + 1
            ) /
            2
      ) /
        (
          n1 *
            n0
        )
    }

    auprc_local <- function(y, p) {
      n_pos <- sum(
        y == 1L
      )

      if (
        n_pos == 0L
      ) {
        return(
          NA_real_
        )
      }

      ord <- order(
        p,
        decreasing = TRUE
      )
      ys <- y[
        ord
      ]

      tp <- cumsum(
        ys == 1L
      )
      fp <- cumsum(
        ys == 0L
      )

      precision <- tp /
        (
          tp +
            fp
        )
      recall <- tp /
        n_pos
      recall_previous <- c(
        0,
        head(
          recall,
          -1L
        )
      )

      sum(
        precision *
          (
            recall -
              recall_previous
          ),
        na.rm = TRUE
      )
    }

    c(
      AUROC =
        auc_local(
          yy,
          pp
        ),
      AUPRC =
        auprc_local(
          yy,
          pp
        ),
      Brier =
        mean(
          (
            pp -
              yy
          )^2
        )
    )
  }

  cl <- parallel::makeCluster(
    workers
  )
  on.exit(
    parallel::stopCluster(
      cl
    ),
    add = TRUE
  )

  reps <- parallel::parLapply(
    cl,
    seq_len(
      B
    ),
    worker_metric,
    y = y,
    p = p,
    seed = seed
  )

  reps <- do.call(
    rbind,
    reps
  )

  data.table(
    N = point$N,
    events = point$events,
    prevalence = point$prevalence,
    AUROC = point$AUROC,
    AUROC_low =
      quantile(
        reps[
          ,
          "AUROC"
        ],
        0.025,
        na.rm = TRUE
      ),
    AUROC_high =
      quantile(
        reps[
          ,
          "AUROC"
        ],
        0.975,
        na.rm = TRUE
      ),
    AUPRC = point$AUPRC,
    AUPRC_low =
      quantile(
        reps[
          ,
          "AUPRC"
        ],
        0.025,
        na.rm = TRUE
      ),
    AUPRC_high =
      quantile(
        reps[
          ,
          "AUPRC"
        ],
        0.975,
        na.rm = TRUE
      ),
    AUPRC_to_prevalence =
      point$AUPRC_to_prevalence,
    Brier = point$Brier,
    Brier_low =
      quantile(
        reps[
          ,
          "Brier"
        ],
        0.025,
        na.rm = TRUE
      ),
    Brier_high =
      quantile(
        reps[
          ,
          "Brier"
        ],
        0.975,
        na.rm = TRUE
      ),
    calibration_intercept =
      point$calibration_intercept,
    calibration_slope =
      point$calibration_slope,
    bootstrap_B =
      B
  )
}

bootstrap_duration_ci <- function(
    y,
    q10,
    q50,
    q90,
    B = B_DURATION,
    seed = 20260913L
) {
  point <- duration_metrics(
    y,
    q10,
    q50,
    q90
  )

  set.seed(
    seed
  )

  reps <- matrix(
    NA_real_,
    nrow = B,
    ncol = 4L
  )

  colnames(
    reps
  ) <- c(
    "MAE",
    "pinball",
    "coverage",
    "width"
  )

  n <- length(
    y
  )

  for (
    b in seq_len(
      B
    )
  ) {
    idx <- sample.int(
      n,
      replace = TRUE
    )

    yy <- y[
      idx
    ]
    l <- q10[
      idx
    ]
    m <- q50[
      idx
    ]
    u <- q90[
      idx
    ]

    reps[
      b,
      "MAE"
    ] <- mean(
      abs(
        yy -
          m
      )
    )

    reps[
      b,
      "pinball"
    ] <- mean(
      c(
        pinball_loss(
          yy,
          l,
          0.10
        ),
        pinball_loss(
          yy,
          m,
          0.50
        ),
        pinball_loss(
          yy,
          u,
          0.90
        )
      )
    )

    reps[
      b,
      "coverage"
    ] <- mean(
      yy >=
        l &
        yy <=
          u
    )

    reps[
      b,
      "width"
    ] <- median(
      u -
        l
    )
  }

  data.table(
    N =
      point$N,
    median_MAE_days =
      point$median_MAE_days,
    MAE_low =
      quantile(
        reps[
          ,
          "MAE"
        ],
        0.025
      ),
    MAE_high =
      quantile(
        reps[
          ,
          "MAE"
        ],
        0.975
      ),
    mean_pinball =
      point$mean_pinball,
    pinball_low =
      quantile(
        reps[
          ,
          "pinball"
        ],
        0.025
      ),
    pinball_high =
      quantile(
        reps[
          ,
          "pinball"
        ],
        0.975
      ),
    central_80_coverage =
      point$central_80_coverage,
    coverage_low =
      quantile(
        reps[
          ,
          "coverage"
        ],
        0.025
      ),
    coverage_high =
      quantile(
        reps[
          ,
          "coverage"
        ],
        0.975
      ),
    median_80_range_width_days =
      point$median_80_range_width_days,
    width_low =
      quantile(
        reps[
          ,
          "width"
        ],
        0.025
      ),
    width_high =
      quantile(
        reps[
          ,
          "width"
        ],
        0.975
      ),
    empirical_q10 =
      point$empirical_q10,
    empirical_q50 =
      point$empirical_q50,
    empirical_q90 =
      point$empirical_q90,
    bootstrap_B =
      B
  )
}

flexible_calibration_curve <- function(
    y,
    p,
    n_grid = 150L
) {
  p <- clamp_prob(
    p
  )
  y <- as.integer(
    y
  )

  lp <- qlogis(
    p
  )

  fit <- glm(
    y ~ splines::ns(
      lp,
      df = 4
    ),
    family = binomial()
  )

  q <- quantile(
    p,
    probs = c(
      0.005,
      0.995
    ),
    na.rm = TRUE
  )

  grid_p <- seq(
    q[1L],
    q[2L],
    length.out = n_grid
  )

  newdata <- data.frame(
    lp =
      qlogis(
        clamp_prob(
          grid_p
        )
      )
  )

  pr <- predict(
    fit,
    newdata = newdata,
    type = "link",
    se.fit = TRUE
  )

  eta <- as.numeric(
    pr$fit
  )
  se <- as.numeric(
    pr$se.fit
  )

  data.table(
    predicted_probability =
      grid_p,
    calibrated_probability =
      plogis(
        eta
      ),
    lower_95 =
      plogis(
        eta -
          1.96 *
            se
      ),
    upper_95 =
      plogis(
        eta +
          1.96 *
            se
      )
  )
}

prob_col <- function(label) {
  paste0(
    "p__",
    make.names(
      label,
      unique = TRUE
    )
  )
}

