# -----------------------------------------------------------------------------
# Build binary target extracts from prediction caches
# -----------------------------------------------------------------------------

extract_targets <- function(
    cache,
    endpoint_id
) {
  spec <- class_specs[[endpoint_id]]
  out <- list()

  if (
    endpoint_id %in%
      c(
        "icp_pressure_monitor_final",
        "craniotomy_craniectomy_final"
      )
  ) {
    out[[1L]] <- data.table(
      endpoint_id =
        endpoint_id,
      endpoint_label =
        spec$label,
      target =
        spec$label,
      observed =
        as.integer(
          cache$observed
        ),
      probability =
        as.numeric(
          cache$predicted_probability
        )
    )

    return(
      out
    )
  }

  for (
    class_label in spec$classes
  ) {
    pc <- prob_col(
      class_label
    )

    if (
      !pc %in%
        names(
          cache
        )
    ) {
      stop(
        "Prediction column missing: ",
        pc,
        call. = FALSE
      )
    }

    out[[
      length(
        out
      ) +
        1L
    ]] <- data.table(
      endpoint_id =
        endpoint_id,
      endpoint_label =
        spec$label,
      target =
        class_label,
      observed =
        as.integer(
          as.character(
            cache$observed
          ) ==
            class_label
        ),
      probability =
        as.numeric(
          cache[[pc]]
        )
    )
  }

  if (
    !is.null(
      spec$derived
    )
  ) {
    ref <- spec$derived$reference_class
    pc <- prob_col(
      ref
    )

    out[[
      length(
        out
      ) +
        1L
    ]] <- data.table(
      endpoint_id =
        endpoint_id,
      endpoint_label =
        spec$label,
      target =
        spec$derived$label,
      observed =
        as.integer(
          as.character(
            cache$observed
          ) !=
            ref
        ),
      probability =
        1 -
          as.numeric(
            cache[[pc]]
          )
    )
  }

  out
}

# -----------------------------------------------------------------------------
# Year-specific and pooled OOF classification metrics
# -----------------------------------------------------------------------------

year_rows <- list()
pooled_target_data <- list()

for (
  endpoint_id in names(
    class_specs
  )
) {
  pooled_parts <- list()

  for (
    year in 2022:2024
  ) {
    fold_name <- paste0(
      "TEST_",
      year
    )

    f <- file.path(
      pred_dir,
      paste0(
        fold_name,
        "__",
        endpoint_id,
        "__final_predictions.rds"
      )
    )

    if (
      !file.exists(
        f
      )
    ) {
      stop(
        "Missing prediction cache: ",
        f,
        call. = FALSE
      )
    }

    cache <- as.data.table(
      readRDS(
        f
      )
    )

    targets <- extract_targets(
      cache,
      endpoint_id
    )

    for (
      d in targets
    ) {
      met <- binary_metrics(
        d$observed,
        d$probability
      )

      met[
        ,
        `:=`(
          year =
            year,
          endpoint_id =
            d$endpoint_id[1L],
          endpoint_label =
            d$endpoint_label[1L],
          target =
            d$target[1L]
        )
      ]

      year_rows[[
        length(
          year_rows
        ) +
          1L
      ]] <- met

      pooled_parts[[
        paste0(
          year,
          "__",
          d$target[1L]
        )
      ]] <- copy(
        d
      )[
        ,
        year :=
          year
      ]
    }
  }

  pooled_target_data[[
    endpoint_id
  ]] <- rbindlist(
    pooled_parts,
    fill = TRUE
  )
}

year_metrics <- rbindlist(
  year_rows,
  fill = TRUE
)

fwrite(
  year_metrics[
    order(
      endpoint_label,
      target,
      year
    )
  ],
  file.path(
    out_dir,
    "01_CLASSIFICATION_YEAR_SPECIFIC_METRICS.csv"
  )
)

pooled_rows <- list()

for (
