        years =
          "2022-2024 rolling-origin OOF",
        endpoint_id =
          endpoint_id,
        endpoint_label =
          dd$endpoint_label[1L],
        target =
          target_name
      )
    ]

    pooled_rows[[
      length(
        pooled_rows
      ) +
        1L
    ]] <- met
  }
}

