# -----------------------------------------------------------------------------
# 2024 bootstrap CIs for headline classification targets
# -----------------------------------------------------------------------------

headline_ci_rows <- list()

for (
  i in seq_len(
    nrow(
      headline_targets
    )
  )
) {
  endpoint_id <- headline_targets$endpoint_id[i]
  target_name <- headline_targets$target[i]

  fold_name <- "TEST_2024"

  f <- file.path(
    pred_dir,
    paste0(
      fold_name,
      "__",
      endpoint_id,
      "__final_predictions.rds"
    )
  )

  cache <- as.data.table(
    readRDS(
      f
    )
  )

  targets <- extract_targets(
    cache,
    endpoint_id
  )

  d <- rbindlist(
    targets,
    fill = TRUE
  )[
    target ==
      target_name
  ]

  if (
    nrow(
      d
    ) ==
      0L
  ) {
    stop(
      "Could not recover headline target: ",
      endpoint_id,
      " / ",
      target_name,
      call. = FALSE
    )
  }

  cat(
    "\nBootstrap classification CI: ",
    target_name,
    "\n",
    sep = ""
  )

  ci <- bootstrap_binary_ci(
    d$observed,
    d$probability,
    B = B_CLASSIFICATION,
    workers = BOOTSTRAP_WORKERS,
    seed =
      20260913L +
        i *
          1000L
  )

  ci[
    ,
    `:=`(
      year =
        2024L,
      endpoint_id =
        endpoint_id,
      endpoint_label =
        d$endpoint_label[1L],
      target =
        target_name
    )
  ]

  headline_ci_rows[[
    length(
      headline_ci_rows
    ) +
      1L
  ]] <- ci
}

headline_ci <- rbindlist(
  headline_ci_rows,
  fill = TRUE
)

fwrite(
  headline_ci,
  file.path(
    out_dir,
    "03_2024_HEADLINE_CLASSIFICATION_BOOTSTRAP_CI.csv"
  )
)

# -----------------------------------------------------------------------------
# Flexible 2024 calibration curves
# -----------------------------------------------------------------------------

calibration_rows <- list()
calibration_group_rows <- list()

for (
  i in seq_len(
    nrow(
      headline_targets
    )
  )
) {
  endpoint_id <- headline_targets$endpoint_id[i]
  target_name <- headline_targets$target[i]

  f <- file.path(
    pred_dir,
    paste0(
      "TEST_2024__",
      endpoint_id,
      "__final_predictions.rds"
    )
  )

  cache <- as.data.table(
    readRDS(
      f
    )
  )

  d <- rbindlist(
    extract_targets(
      cache,
      endpoint_id
    ),
    fill = TRUE
  )[
    target ==
      target_name
  ]

  curve <- flexible_calibration_curve(
    d$observed,
    d$probability
  )

  curve[
    ,
    `:=`(
      endpoint_id =
        endpoint_id,
      endpoint_label =
        d$endpoint_label[1L],
      target =
        target_name,
      year =
        2024L
    )
  ]

  calibration_rows[[
    length(
      calibration_rows
    ) +
      1L
  ]] <- curve

  # Decile points are supplemental visual anchors only; the smooth curve is
  # the primary calibration assessment.
  dd <- data.table(
    y =
      d$observed,
    p =
      d$probability
  )

  dd[
    ,
    group :=
      pmin(
        10L,
        pmax(
          1L,
          ceiling(
            10 *
              frank(
                p,
                ties.method = "average"
              ) /
              .N
          )
        )
      )
  ]

  gp <- dd[
    ,
    .(
      N =
        .N,
      mean_predicted =
        mean(
          p
        ),
      observed =
        mean(
          y
        )
    ),
    by = group
  ]

  gp[
    ,
    `:=`(
      endpoint_id =
        endpoint_id,
      endpoint_label =
        d$endpoint_label[1L],
      target =
        target_name,
      year =
        2024L
    )
  ]

  calibration_group_rows[[
    length(
      calibration_group_rows
    ) +
      1L
  ]] <- gp
}

calibration_curves <- rbindlist(
  calibration_rows,
  fill = TRUE
)

calibration_points <- rbindlist(
  calibration_group_rows,
  fill = TRUE
)

fwrite(
  calibration_curves,
  file.path(
    out_dir,
    "04_2024_FLEXIBLE_CALIBRATION_CURVES.csv"
  )
)

fwrite(
