    "05_2024_CALIBRATION_DECILE_POINTS.csv"
  )
)

# -----------------------------------------------------------------------------
# Duration metrics, bootstrap CIs, and calibration bins
# -----------------------------------------------------------------------------

duration_year_rows <- list()
duration_ci_rows <- list()
duration_calibration_rows <- list()

for (
  duration_id in names(
    duration_specs
  )
) {
  label <- duration_specs[[
    duration_id
  ]]

  for (
    year in 2022:2024
  ) {
    f <- file.path(
      pred_dir,
      paste0(
        "TEST_",
        year,
        "__",
        duration_id,
        "__final_duration_predictions.rds"
      )
    )

    cache <- as.data.table(
      readRDS(
        f
      )
    )

    met <- duration_metrics(
      cache$observed_days,
      cache$q10,
      cache$q50,
      cache$q90
    )

    met[
      ,
      `:=`(
        year =
          year,
        duration_id =
          duration_id,
        duration_label =
          label
      )
    ]

    duration_year_rows[[
      length(
        duration_year_rows
      ) +
        1L
    ]] <- met

    if (
      year ==
        2024L
    ) {
      cat(
        "\nBootstrap duration CI: ",
        label,
        "\n",
        sep = ""
      )

      ci <- bootstrap_duration_ci(
        cache$observed_days,
        cache$q10,
        cache$q50,
        cache$q90,
        B = B_DURATION,
        seed =
          20260913L +
            length(
              duration_ci_rows
            ) *
              1000L
      )

      ci[
        ,
        `:=`(
          year =
            2024L,
          duration_id =
            duration_id,
          duration_label =
            label
        )
      ]

      duration_ci_rows[[
        length(
          duration_ci_rows
        ) +
          1L
      ]] <- ci

      d <- copy(
        cache
      )

      d[
        ,
        bin :=
          pmin(
            20L,
            pmax(
              1L,
              ceiling(
                20 *
                  frank(
                    q50,
                    ties.method = "average"
                  ) /
                  .N
              )
            )
          )
      ]

      cal <- d[
        ,
        .(
          N =
            .N,
          predicted_median =
            median(
              q50
            ),
          observed_median =
            median(
              observed_days
            ),
          predicted_q10 =
            median(
              q10
            ),
          predicted_q90 =
            median(
              q90
            ),
          observed_q10 =
            quantile(
              observed_days,
              0.10
            ),
          observed_q90 =
            quantile(
              observed_days,
              0.90
            )
        ),
        by = bin
      ]

      cal[
        ,
        `:=`(
          duration_id =
            duration_id,
          duration_label =
            label,
          year =
            2024L
        )
      ]

      duration_calibration_rows[[
        length(
          duration_calibration_rows
        ) +
          1L
      ]] <- cal
    }
  }
}

duration_year <- rbindlist(
  duration_year_rows,
  fill = TRUE
)

duration_ci <- rbindlist(
  duration_ci_rows,
  fill = TRUE
)

duration_calibration <- rbindlist(
  duration_calibration_rows,
  fill = TRUE
)

fwrite(
